    "faqQuestion1": "The Detective Archive เป็นเว็บไซต์ Silver Palace อย่างเป็นทางการหรือไม่?",
    "faqAnswer1": "ไม่ The Detective Archive เป็นฐานข้อมูลที่แฟนสร้างขึ้นอย่างอิสระ และไม่ได้เกี่ยวข้องหรือได้รับการรับรองจาก Elementa",
    "faqQuestion2": "ทำไมค่าสถานะ พาสซีฟ หรือคะแนนอันดับบางอย่างจึงว่าง?",
    "faqAnswer2": "Silver Palace ยังไม่เปิดตัว เมื่อค่าใดไม่สามารถตรวจสอบได้อย่างน่าเชื่อถือ คลังจะเว้นว่างแทนการประมาณหรือแต่งขึ้น",
    "faqQuestion3": "ตัวเลข CBT2 เป็นค่ final หรือไม่?",
    "faqAnswer3": "ไม่ Dichotomy CBT2 เป็นบิลด์ระหว่างพัฒนา สกิล ค่าสถานะ คำศัพท์ อุปกรณ์ การได้รับ และสมดุลอาจเปลี่ยนก่อนวางจำหน่าย",
    "faqQuestion4": "Motive คืออะไร?",
    "faqAnswer4": "Motive คืออุปกรณ์ที่สวมใส่ได้ ให้ค่าสถานะตัวละครและ Motive Skill โดย Identity กำหนดว่าตัวละครใดใช้ได้",
    "faqQuestion5": "Simulation Implement กับ Epiphany ต่างกันอย่างไร?",
    "faqAnswer5": "Simulation ใช้ช่อง Implement 4 ช่องที่ประกอบเป็นเซ็ตอุปกรณ์ ส่วน Epiphany ใช้ช่องหนังสือแยกและเป็นชั้นซับสเตตแบบสุ่มที่พบใน CBT2",
    "faqQuestion6": "Psyche คืออะไร?",
    "faqAnswer6": "Psyche คือการอัปเกรดตัวละครจากการได้ซ้ำ คลัง CBT2 ปัจจุบันบันทึก Psyche 6 ระดับ P1 ถึง P6 สำหรับตัวละครที่เล่นได้แต่ละตัว",
    "faqQuestion7": "ทำไมคะแนน Character Ranking ยังไม่เผยแพร่?",
    "faqAnswer7": "คะแนนจะเผยแพร่เมื่อมีข้อมูลการต่อสู้ที่เปรียบเทียบกันได้และวิธีให้คะแนนตามบทบาทที่ทำซ้ำได้ คลังจะไม่ใส่คะแนนชั่วคราว",
    "faqQuestion8": "ทำไม Player Lookup ยังใช้ไม่ได้?",
    "faqAnswer8": "การค้นหา UID ต้องใช้แหล่งข้อมูลผู้เล่น Silver Palace แบบสาธารณะหรือทางการที่เชื่อถือได้ ฟีเจอร์นี้จะเป็นตัวอย่างไว้จนกว่าจะมีแหล่งดังกล่าว",
