    "faqQuestion1": "The Detective Archive 是 Silver Palace 官方网站吗？",
    "faqAnswer1": "不是。The Detective Archive 是独立的玩家制作数据库，与 Elementa 无隶属关系，也未获得其官方背书。",
    "faqQuestion2": "为什么有些属性、被动或排行评分会留空？",
    "faqAnswer2": "Silver Palace 仍处于正式发布前阶段。当某个数值无法可靠验证时，档案会选择留空，而不是估算或臆造。",
