    "faqQuestion4": "Motive 是什么？",
    "faqAnswer4": "Motive 是可装备物品，可提供角色属性与一个 Motive Skill。它的 Identity 决定哪些角色可以使用。",
    "faqQuestion5": "Simulation Implement 与 Epiphany 有什么区别？",
    "faqAnswer5": "Simulation 使用四个组成装备套装的 Implement 槽位。Epiphany 占用独立书籍槽位，是 CBT2 中观察到的可随机副属性层。",
    "faqQuestion6": "Psyche 是什么？",
    "faqAnswer6": "Psyche 是角色重复获取后的升级。当前 CBT2 档案为每个可玩角色记录了 P1 到 P6 共六级 Psyche。",
    "faqQuestion7": "为什么 Character Ranking 评分仍未发布？",
    "faqAnswer7": "只有在具备可比战斗数据和可重复、按角色定位设计的评分方法后才会发布。档案不会填写占位评分。",
    "faqQuestion8": "为什么 Player Lookup 还不能使用？",
