    "helpFaqTitle": "아카이브 FAQ",
    "faqQuestion1": "The Detective Archive는 Silver Palace 공식 웹사이트인가요?",
    "faqAnswer1": "아닙니다. The Detective Archive는 독립적인 팬 제작 데이터베이스이며 Elementa와 제휴하거나 공식 승인을 받은 사이트가 아닙니다.",
    "faqQuestion2": "일부 스탯, 패시브, 랭킹 점수가 비어 있는 이유는 무엇인가요?",
    "faqAnswer2": "Silver Palace는 아직 출시 전입니다. 값을 신뢰할 수 있게 검증할 수 없으면 추정하거나 만들어내지 않고 비워 둡니다.",
    "faqQuestion3": "CBT2 수치는 최종값인가요?",
    "faqAnswer3": "아닙니다. Dichotomy CBT2는 개발 빌드입니다. 스킬, 스탯, 용어, 장비, 입수 방식, 밸런스는 출시 전에 변경될 수 있습니다.",
    "faqQuestion4": "Motive란 무엇인가요?",
    "faqAnswer4": "Motive는 캐릭터 스탯과 Motive Skill을 제공하는 장착 장비입니다. Identity에 따라 사용할 수 있는 캐릭터가 결정됩니다.",
    "faqQuestion5": "Simulation Implement와 Epiphany의 차이는 무엇인가요?",
    "faqAnswer5": "Simulation은 장비 세트를 구성하는 Implement 슬롯 4개를 사용합니다. Epiphany는 별도 책 슬롯을 사용하며 CBT2에서 관측된 롤 가능한 부옵션 층입니다.",
    "faqQuestion6": "Psyche란 무엇인가요?",
    "faqAnswer6": "Psyche는 캐릭터 중복 획득 강화입니다. 현재 CBT2 아카이브는 각 플레이어블 캐릭터마다 P1부터 P6까지 6단계를 기록합니다.",
    "faqQuestion7": "Character Ranking 점수가 아직 공개되지 않은 이유는 무엇인가요?",
    "faqAnswer7": "비교 가능한 전투 데이터와 반복 가능한 역할 기반 채점 방식이 마련된 뒤에만 공개합니다. 아카이브는 임시 점수를 넣지 않습니다.",
    "faqQuestion8": "Player Lookup이 아직 작동하지 않는 이유는 무엇인가요?",
    "faqAnswer8": "UID 조회에는 신뢰할 수 있는 공개 또는 공식 Silver Palace 플레이어 데이터 소스가 필요합니다. 그런 소스가 생길 때까지 자리표시자로 유지됩니다.",
    "helpSourceLabel": "출처 메모",
    "helpSourceTitle": "아카이브 출처 방식",
    "helpSourceIntro": "캐릭터 스킬과 데이터베이스 카드를 깔끔하게 유지하기 위해 출처 라벨을 이곳에 모아 표시합니다.",
    "helpOfficialBadge": "공식",
