    "epiphanyLiteraryMappingNote": "Les 30 Epiphanies de Dichotomy CBT2 sont associées à des œuvres littéraires publiées. Le champ de source littéraire enregistre cette correspondance et est distinct du passif de gameplay.",
    "psycheSystem": "Parcours Psyche",
    "psycheSystemDescription": "Les Psyches sont des améliorations obtenues par copies supplémentaires. Chaque personnage possède six Psyches ; sept exemplaires au total débloquent le parcours complet P1–P6. Les valeurs affichées proviennent de Dichotomy CBT2 et peuvent changer avant la sortie.",
    "help": "Aide",
    "helpCenterTag": "ASSISTANCE DE L'ARCHIVE",
    "helpCenterTitle": "Centre d'aide",
    "helpCenterDescription": "Questions fréquentes, règles de l'archive et politique de sources utilisée par The Detective Archive.",
    "helpFaqLabel": "QUESTIONS FRÉQUENTES",
    "helpFaqTitle": "FAQ de l'archive",
    "faqQuestion1": "The Detective Archive est-il un site officiel de Silver Palace ?",
    "faqAnswer1": "Non. The Detective Archive est une base de données indépendante créée par des fans, sans affiliation ni approbation d'Elementa.",
    "faqQuestion2": "Pourquoi certaines statistiques, certains passifs ou scores de classement sont-ils vides ?",
    "faqAnswer2": "Silver Palace est encore en pré-sortie. Lorsqu'une valeur ne peut pas être vérifiée de manière fiable, l'archive la laisse vide au lieu de l'estimer ou de l'inventer.",
    "faqQuestion3": "Les valeurs CBT2 sont-elles définitives ?",
    "faqAnswer3": "Non. Dichotomy CBT2 est une version en développement. Les compétences, statistiques, termes, équipements, disponibilités et l'équilibrage peuvent changer avant la sortie.",
    "faqQuestion4": "Qu'est-ce qu'un Motive ?",
    "faqAnswer4": "Un Motive est un équipement qui fournit des statistiques au personnage et une Motive Skill. Son Identity détermine quels personnages peuvent l'utiliser.",
    "faqQuestion5": "Quelle est la différence entre les Simulation Implements et Epiphany ?",
    "faqAnswer5": "Simulation utilise quatre emplacements d'Implements formant des sets d'équipement. Epiphany occupe un emplacement de livre séparé et constitue la couche de sous-statistiques à jets observée dans CBT2.",
    "faqQuestion6": "Que sont les Psyches ?",
    "faqAnswer6": "Les Psyches sont des améliorations de personnage obtenues par copies supplémentaires. L'archive CBT2 actuelle enregistre six niveaux, de P1 à P6, pour chaque personnage jouable.",
    "faqQuestion7": "Pourquoi les scores du classement des personnages ne sont-ils pas encore publiés ?",
    "faqAnswer7": "Les scores ne seront publiés qu'une fois disponibles des données de combat comparables et une méthode de notation reproductible tenant compte des rôles. L'archive n'attribue pas de scores temporaires.",
    "faqQuestion8": "Pourquoi Player Lookup ne fonctionne-t-il pas encore ?",
    "faqAnswer8": "La recherche par UID nécessite une source publique ou officielle fiable de données de joueurs Silver Palace. La fonction reste un espace réservé jusqu'à l'existence d'une telle source.",
    "helpSourceLabel": "NOTES SUR LES SOURCES",
    "helpSourceTitle": "Comment l'archive est sourcée",
    "helpSourceIntro": "Les labels de sources sont centralisés ici afin de garder les compétences et cartes de base de données claires et faciles à lire.",
    "helpOfficialBadge": "OFFICIEL",
    "helpOfficialText": "Utilisé pour les annonces officielles, règles de bêta, statut du jeu et informations publiées directement par l'équipe Silver Palace.",
    "helpOfficialLink": "Site officiel de Silver Palace ↗",
    "helpBetaTranscriptBadge": "TRANSCRIPTION BÊTA",
    "helpKaidenText": "Utilisé principalement pour les textes de compétences CBT2, mécaniques, valeurs numériques observées, lignes d'amélioration et autres données transcrites du client bêta.",
    "helpKaidenLink": "Kaiden.gg Silver Palace ↗",
    "helpCommunityBadge": "RÉFÉRENCE COMMUNAUTAIRE",
    "helpMetaText": "Utilisé pour recouper les systèmes CBT2 tels que Motives, Simulation, Epiphany, la terminologie, les observations bêta et les correspondances de sources littéraires.",
    "helpMetaLink": "Guides SilverPalaceMeta ↗",
    "helpPolicyLabel": "POLITIQUE DE L'ARCHIVE",
    "helpPolicy1": "Les informations officielles sont prioritaires lorsqu'une source officielle existe.",
    "helpPolicy2": "Les observations directes et transcriptions CBT2 sont traitées comme des données bêta, non comme des données de sortie.",
    "helpPolicy3": "Les sources communautaires sont recoupées lorsque possible ; les valeurs contradictoires ou incertaines restent non publiées.",
