    "helpFaqLabel": "PREGUNTAS FRECUENTES",
    "helpFaqTitle": "FAQ del archivo",
    "faqQuestion1": "¿The Detective Archive es un sitio oficial de Silver Palace?",
    "faqAnswer1": "No. The Detective Archive es una base de datos independiente creada por fans y no está afiliada ni respaldada por Elementa.",
    "faqQuestion2": "¿Por qué algunas estadísticas, pasivas o puntuaciones de ranking pueden estar vacías?",
    "faqAnswer2": "Silver Palace aún está en fase previa al lanzamiento. Cuando un valor no puede verificarse de forma fiable, el archivo lo deja vacío en lugar de estimarlo o inventarlo.",
    "faqQuestion3": "¿Los números de CBT2 son definitivos?",
    "faqAnswer3": "No. Dichotomy CBT2 es una versión en desarrollo. Las habilidades, estadísticas, terminología, equipo, disponibilidad y balance pueden cambiar antes del lanzamiento.",
    "faqQuestion4": "¿Qué es un Motive?",
    "faqAnswer4": "Un Motive es equipo que proporciona estadísticas al personaje y una Motive Skill. Su Identity determina qué personajes pueden usarlo.",
    "faqQuestion5": "¿Cuál es la diferencia entre Simulation Implements y Epiphany?",
    "faqAnswer5": "Simulation utiliza cuatro ranuras de Implements que forman sets de equipo. Epiphany ocupa una ranura de libro separada y es la capa de substats con tiradas observada en CBT2.",
    "faqQuestion6": "¿Qué son las Psyches?",
    "faqAnswer6": "Las Psyches son mejoras de personaje obtenidas con copias duplicadas. El archivo CBT2 actual registra seis niveles, P1 a P6, para cada personaje jugable.",
    "faqQuestion7": "¿Por qué las puntuaciones de Character Ranking siguen sin publicarse?",
